<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Ammonia Plant Process Flow Diagram</title>
    <style>
        :root {
            --bg-app: #121212;
            --bg-sheet: #1e1e1e;
            --bg-sidebar: #1a1a1a;
            --text-main: #e0e0e0;
            --text-muted: #888888;
            --accent: #4a9eff;
            --border-color: #333;
            --shadow-soft: 0 10px 30px rgba(0,0,0,0.5);

            /* Stream Colors */
            --c-feed: #ffcc00; /* Yellow-ish */
            --c-process: #4a9eff; /* Blue */
            --c-condensate: #00cc99; /* Teal */
            --c-co2: #ff5555; /* Red */
            --c-product: #ffffff; /* White */
            --c-recycle: #aaaaaa; /* Grey */
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-app);
            color: var(--text-main);
            height: 100vh;
            display: flex;
            flex-direction: column;
            overflow: hidden;
        }

        /* --- Header --- */
        header {
            height: 60px;
            background-color: var(--bg-sidebar);
            border-bottom: 1px solid var(--border-color);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 20px;
            z-index: 10;
        }

        .header-left {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .back-btn {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            border: none;
            background: transparent;
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
        }

        .plant-title h1 {
            font-size: 16px;
            font-weight: 600;
        }

        .plant-title p {
            font-size: 11px;
            color: var(--text-muted);
        }

        .header-right {
            display: flex;
            gap: 12px;
            align-items: center;
        }

        .btn-pill {
            padding: 6px 16px;
            border-radius: 20px;
            border: 1px solid var(--border-color);
            background: transparent;
            color: var(--text-main);
            font-size: 13px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .btn-pill.active {
            background: white;
            color: black;
            border-color: white;
        }

        .icon-btn {
            background: none;
            border: none;
            color: var(--text-muted);
            cursor: pointer;
            font-size: 18px;
        }

        /* --- Main Layout --- */
        main {
            flex: 1;
            display: grid;
            grid-template-columns: 1fr 320px;
            overflow: hidden;
        }

        /* --- Canvas Area (Left) --- */
        .canvas-container {
            position: relative;
            overflow: hidden;
            background-color: var(--bg-app); /* Darker bg behind sheet */
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 40px;
        }

        .hint-bar {
            position: absolute;
            top: 20px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(255,255,255,0.1);
            padding: 6px 16px;
            border-radius: 20px;
            font-size: 12px;
            color: var(--text-muted);
            pointer-events: none;
        }

        /* The Continuous Sheet */
        .pfd-sheet {
            width: 100%;
            max-width: 1200px;
            aspect-ratio: 16/9;
            background-color: var(--bg-sheet);
            border: 1px solid #333;
            border-radius: 8px;
            box-shadow: var(--shadow-soft);
            position: relative;
            padding: 30px;
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        /* Section Dividers & Headers inside Sheet */
        .section-header {
            position: absolute;
            left: 20px;
            font-size: 10px;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--text-muted);
            font-weight: 700;
            border-bottom: 1px solid #444;
            padding-bottom: 3px;
            margin-bottom: 5px;
            display: inline-block;
        }

        .sec-1 { top: 25px; }
        .sec-2 { top: 25px; left: 35%; } /* Approximate positioning based on visual flow */
        .sec-3 { top: 48%; left: 20px; }

        /* SVG Layer for Diagram */
        .diagram-layer {
            flex: 1;
            width: 100%;
            height: 100%;
            position: absolute;
            top: 0;
            left: 0;
        }

        svg {
            width: 100%;
            height: 100%;
            overflow: visible;
        }

        /* SVG Elements Styling */
        .stream-line {
            fill: none;
            stroke-width: 2;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .stream-arrow {
            fill: currentColor;
        }

        .equip-shape {
            fill: var(--bg-sheet);
            stroke: #888;
            stroke-width: 1.5;
            filter: drop-shadow(0 2px 4px rgba(0,0,0,0.3)); /* Lift effect */
        }

        .equip-text {
            fill: #ddd;
            font-family: monospace;
            font-size: 10px;
            text-anchor: middle;
            pointer-events: none;
        }

        .equip-label {
            fill: #aaa;
            font-size: 8px;
            text-anchor: middle;
            text-transform: uppercase;
        }

        .stream-num {
            fill: #fff;
            font-size: 9px;
            font-weight: bold;
            text-anchor: middle;
        }

        .num-circle {
            fill: rgba(0,0,0,0.5);
            r: 7;
        }

        /* Sidebar (Right) */
        aside {
            background-color: var(--bg-sidebar);
            border-left: 1px solid var(--border-color);
            padding: 24px;
            display: flex;
            flex-direction: column;
            gap: 20px;
            overflow-y: auto;
        }

        aside h2 {
            font-size: 18px;
            line-height: 1.4;
            margin-bottom: 8px;
        }

        aside p {
            font-size: 13px;
            color: var(--text-muted);
            line-height: 1.5;
            margin-bottom: 20px;
        }

        .menu-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .menu-item {
            background: #262626;
            border: 1px solid #333;
            padding: 14px 16px;
            border-radius: 6px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            cursor: pointer;
            transition: background 0.2s;
            font-size: 13px;
            font-weight: 500;
        }

        .menu-item:hover {
            background: #333;
            border-color: #555;
        }

        .menu-item::after {
            content: '→';
            opacity: 0.5;
        }

        /* Footer / Legend Overlay on Canvas */
        .legend-container {
            position: absolute;
            bottom: 20px;
            left: 20px;
            display: flex;
            align-items: center;
            gap: 15px;
            background: rgba(18,18,18,0.9);
            padding: 8px 16px;
            border-radius: 20px;
            border: 1px solid #333;
            backdrop-filter: blur(4px);
            z-index: 5;
        }

        .compass {
            width: 28px;
            height: 28px;
            background: black;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            font-size: 12px;
            border: 1px solid #444;
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 10px;
            color: #ccc;
            text-transform: uppercase;
        }

        .l-line { width: 20px; height: 2px; }
        .l-dash { 
            width: 20px; height: 0; 
            border-top: 2px dashed currentColor; 
        }

        .zoom-controls {
            position: absolute;
            bottom: 20px;
            right: 340px; /* Offset from sidebar */
            display: flex;
            background: #222;
            border: 1px solid #444;
            border-radius: 4px;
            overflow: hidden;
            z-index: 5;
        }

        .z-btn {
            width: 32px;
            height: 32px;
            border: none;
            background: transparent;
            color: #fff;
            cursor: pointer;
            font-size: 16px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .z-btn:hover { background: #333; }
        .z-divider { width: 1px; background: #444; }
        .z-label { 
            padding: 0 10px; 
            font-size: 11px; 
            display: flex; 
            align-items: center; 
            color: #aaa;
            font-weight: 600;
        }

        /* Title Block in SVG */
        .title-block rect {
            fill: #252525;
            stroke: #444;
            stroke-width: 1;
        }
        .title-block text {
            fill: #bbb;
            font-size: 9px;
            font-family: monospace;
        }

    </style>
</head>
<body>

<header>
    <div class="header-left">
        <button class="back-btn">←</button>
        <div class="plant-title">
            <h1>Steam-Methane Reforming Plant</h1>
            <p>Reference plant · 1,000 t/d design · 19 units · 27 streams</p>
        </div>
    </div>
    <div class="header-right">
        <button class="btn-pill active">Explore</button>
        <button class="btn-pill">Operate</button>
        <button class="btn-pill">Learn</button>
        <button class="icon-btn">☀</button>
    </div>
</header>

<main>
    <section class="canvas-container">
        <div class="hint-bar">Drag to pan · scroll to zoom · click any unit or stream</div>

        <!-- Single Continuous Sheet -->
        <div class="pfd-sheet">

            <!-- Internal Captions -->
            <div class="section-header sec-1">1 - Feed & Reforming</div>
            <div class="section-header sec-2">2 - Shift & Purification</div>
            <div class="section-header sec-3">3 - Synthesis Loop & Compression</div>

            <!-- SVG Diagram -->
            <svg viewBox="0 0 1200 650" preserveAspectRatio="xMidYMid meet" class="diagram-layer">
                <defs>
                    <!-- Arrow Marker -->
                    <marker id="arrow-feed" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
                        <path d="M0,0 L6,3 L0,6 Z" fill="#ffcc00"/>
                    </marker>
                    <marker id="arrow-process" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
                        <path d="M0,0 L6,3 L0,6 Z" fill="#4a9eff"/>
                    </marker>
                     <marker id="arrow-cond" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
                        <path d="M0,0 L6,3 L0,6 Z" fill="#00cc99"/>
                    </marker>
                    <marker id="arrow-co2" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
                        <path d="M0,0 L6,3 L0,6 Z" fill="#ff5555"/>
                    </marker>

                    <!-- Equipment Patterns -->
                    <pattern id="stripes" patternUnits="userSpaceOnUse" width="8" height="8" patternTransform="rotate(45)">
                        <line x1="0" y1="0" x2="0" y2="8" stroke="#666" stroke-width="1" />
                    </pattern>
                </defs>

                <!-- ==================== -->
                <!-- SECTION 1: REFORMING  -->
                <!-- ==================== -->

                <!-- Streams -->
                <g id="streams-s1">
                    <!-- Feed Inlets -->
                    <path d="M50,180 H90" stroke="#ffcc00" class="stream-line" marker-end="url(#arrow-feed)"/> <!-- NG -->
                    <circle cx="70" cy="180" r="8" fill="#1e1e1e" stroke="#ffcc00"/><text x="70" y="183" class="stream-num" fill="#ffcc00">1</text>

                    <path d="M50,210 H90" stroke="#ffcc00" class="stream-line" marker-end="url(#arrow-feed)"/> <!-- Steam -->
                    <circle cx="70" cy="210" r="8" fill="#1e1e1e" stroke="#ffcc00"/><text x="70" y="213" class="stream-num" fill="#ffcc00">2</text>

                    <!-- Mixer to Reformer -->
                    <path d="M120,195 H150" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="135" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="135" y="198" class="stream-num">3</text>

                    <!-- Reformer to Secondary -->
                    <path d="M230,195 H280" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="255" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="255" y="198" class="stream-num">4</text>

                    <!-- Process Air -->
                    <path d="M310,110 V145" stroke="#ffcc00" class="stream-line" marker-end="url(#arrow-feed)"/>
                    <circle cx="310" cy="125" r="8" fill="#1e1e1e" stroke="#ffcc00"/><text x="310" y="128" class="stream-num" fill="#ffcc00">5</text>

                    <!-- Secondary to WHB -->
                    <path d="M340,195 H400" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="370" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="370" y="198" class="stream-num">6</text>
                </g>

                <!-- Equipment S1 -->
                <g id="equip-s1">
                    <!-- Mixer M-101 -->
                    <polygon points="90,175 120,195 90,215" class="equip-shape" style="fill:none;" />
                    <text x="105" y="235" class="equip-text">M-101</text>
                    <text x="105" y="245" class="equip-label">Mixer</text>

                    <!-- Primary Reformer K-102 -->
                    <rect x="150" y="160" width="80" height="70" rx="4" class="equip-shape" />
                    <path d="M160,210 L170,190 L180,210 L190,190 L200,210 L210,190 L220,210" fill="none" stroke="#666" stroke-width="1"/>
                    <text x="190" y="245" class="equip-text">K-102</text>
                    <text x="190" y="255" class="equip-label">Primary Reformer</text>

                    <!-- Secondary Reformer K-103 -->
                    <path d="M280,165 H340 V225 H280 Z" class="equip-shape" /> <!-- Simplified vessel -->
                    <rect x="290" y="170" width="40" height="50" fill="url(#stripes)" rx="2"/>
                    <text x="310" y="245" class="equip-text">K-103</text>
                    <text x="310" y="255" class="equip-label">Secondary Reformer</text>

                    <!-- WHB E-101 -->
                    <rect x="400" y="180" width="50" height="30" rx="15" class="equip-shape" />
                    <text x="425" y="225" class="equip-text">E-101</text>
                    <text x="425" y="235" class="equip-label">Waste Heat Boiler</text>
                </g>


                <!-- ==================== -->
                <!-- SECTION 2: PURIFICATION-->
                <!-- ==================== -->

                 <!-- Streams -->
                 <g id="streams-s2">
                    <!-- WHB to HT Shift -->
                    <path d="M450,195 H480" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="465" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="465" y="198" class="stream-num">7</text>

                    <!-- HT Shift to Intercooler -->
                    <path d="M530,195 H560" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="545" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="545" y="198" class="stream-num">8</text>

                    <!-- Intercooler to LT Shift -->
                    <path d="M610,195 H640" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="625" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="625" y="198" class="stream-num">9</text>

                    <!-- LT Shift to KO Drum -->
                    <path d="M690,195 H720" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="705" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="705" y="198" class="stream-num">10</text>

                    <!-- Condensate Drop -->
                    <path d="M755,220 V260" stroke="#00cc99" class="stream-line" marker-end="url(#arrow-cond)"/>
                    <circle cx="755" cy="240" r="8" fill="#1e1e1e" stroke="#00cc99"/><text x="755" y="243" class="stream-num" fill="#00cc99">11</text>
                    <text x="755" y="275" class="equip-label" style="text-anchor:middle;">Condensate</text>

                    <!-- KO Drum to CO2 Removal -->
                    <path d="M790,195 H830" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="810" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="810" y="198" class="stream-num">12</text>

                    <!-- CO2 Removal to Methanator -->
                    <path d="M900,195 H930" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="915" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="915" y="198" class="stream-num">13</text>

                    <!-- CO2 Out -->
                    <path d="M865,230 V270" stroke="#ff5555" class="stream-line" marker-end="url(#arrow-co2)"/>
                    <circle cx="865" cy="250" r="8" fill="#1e1e1e" stroke="#ff5555"/><text x="865" y="253" class="stream-num" fill="#ff5555">14</text>
                    <text x="865" y="285" class="equip-label" style="text-anchor:middle;">CO2 to Storage</text>

                    <!-- Methanator to Final KO -->
                    <path d="M980,195 H1020" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="1000" cy="195" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="1000" y="198" class="stream-num">15</text>

                    <!-- Final KO to Compressor -->
                    <path d="M1060,220 V380" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="1060" cy="300" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="1060" y="303" class="stream-num">16</text>

                    <!-- Condensate 2 -->
                    <path d="M1060,245 V275" stroke="#00cc99" class="stream-line" marker-end="url(#arrow-cond)"/>
                    <circle cx="1060" cy="260" r="8" fill="#1e1e1e" stroke="#00cc99"/><text x="1060" y="263" class="stream-num" fill="#00cc99">17</text>
                </g>

                <!-- Equipment S2 -->
                <g id="equip-s2">
                    <!-- HT Shift R-104 -->
                    <rect x="480" y="170" width="50" height="50" rx="25" class="equip-shape" />
                    <text x="505" y="235" class="equip-text">R-104</text>
                    <text x="505" y="245" class="equip-label">High-Temp Shift</text>

                    <!-- Intercooler E-102 -->
                    <rect x="560" y="182" width="50" height="26" rx="13" class="equip-shape" stroke-dasharray="4 2"/>
                    <text x="585" y="225" class="equip-text">E-102</text>
                    <text x="585" y="235" class="equip-label">Intercooler</text>

                    <!-- LT Shift R-105 -->
                    <rect x="640" y="170" width="50" height="50" rx="25" class="equip-shape" />
                    <text x="665" y="235" class="equip-text">R-105</text>
                    <text x="665" y="245" class="equip-label">Low-Temp Shift</text>

                    <!-- Knockout Drum V-101 -->
                    <path d="M720,175 H790 A10,10 0 0,1 800,185 V205 A10,10 0 0,1 790,215 H720 A10,10 0 0,1 710,205 V185 A10,10 0 0,1 720,175 Z" class="equip-shape" transform="translate(-5,0)"/>
                    <text x="750" y="165" class="equip-text">Knockout Drum</text> <!-- Label above due to drop -->

                    <!-- CO2 Removal C-101 -->
                    <rect x="830" y="150" width="70" height="90" rx="4" class="equip-shape" />
                    <line x1="850" y1="150" x2="850" y2="240" stroke="#555"/>
                    <line x1="880" y1="150" x2="880" y2="240" stroke="#555"/>
                    <text x="865" y="260" class="equip-text">C-101</text>
                    <text x="865" y="270" class="equip-label">CO2 Removal</text>

                    <!-- Methanator R-106 -->
                    <rect x="930" y="170" width="50" height="50" rx="25" class="equip-shape" />
                    <text x="955" y="235" class="equip-text">R-106</text>
                    <text x="955" y="245" class="equip-label">Methanator</text>

                    <!-- Final KO V-102 -->
                    <ellipse cx="1040" cy="195" rx="20" ry="25" class="equip-shape" />
                    <text x="1040" y="165" class="equip-text">V-102</text>
                </g>


                <!-- ==================== -->
                <!-- SECTION 3: SYNTHESIS   -->
                <!-- ==================== -->

                <!-- Streams Loop -->
                <g id="streams-s3">
                    <!-- Comp to Mixer -->
                    <path d="M1030,395 H950" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="990" cy="395" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="990" y="398" class="stream-num">18</text>

                    <!-- Mixer to Preheater -->
                    <path d="M900,395 H830" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="865" cy="395" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="865" y="398" class="stream-num">19</text>

                    <!-- Preheater to Converter -->
                    <path d="M780,395 H710" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="745" cy="395" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="745" y="398" class="stream-num">20</text>

                    <!-- Converter to Cooler/Train -->
                    <path d="M630,395 H560" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="595" cy="395" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="595" y="398" class="stream-num">21</text>

                    <!-- Train to Separator -->
                    <path d="M510,395 H440" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="475" cy="395" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="475" y="398" class="stream-num">22</text>

                    <!-- Sep to Purge Split -->
                    <path d="M390,395 H320" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="355" cy="395" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="355" y="398" class="stream-num">23</text>

                    <!-- Recycle Line (Bottom) -->
                    <path d="M280,420 V520 H1080 V420" stroke="#aaa" class="stream-line" stroke-dasharray="5,3" />
                    <circle cx="300" cy="520" r="8" fill="#1e1e1e" stroke="#aaa"/><text x="300" y="523" class="stream-num" fill="#aaa">24</text>
                    <text x="680" y="535" class="equip-label" style="font-size:10px; fill:#aaa;">RECYCLE</text>

                    <!-- Purge Split to Circulator -->
                    <path d="M280,395 H220" stroke="#4a9eff" class="stream-line" marker-end="url(#arrow-process)"/>
                    <circle cx="250" cy="395" r="8" fill="#1e1e1e" stroke="#4a9eff"/><text x="250" y="398" class="stream-num">25</text>

                    <!-- Purge to Fuel -->
                    <path d="M300,420 V460" stroke="#ffcc00" class="stream-line" marker-end="url(#arrow-feed)"/>
                    <circle cx="300" cy="440" r="8" fill="#1e1e1e" stroke="#ffcc00"/><text x="300" y="443" class="stream-num" fill="#ffcc00">26</text>
